#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.50.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.50.0.json').read_text())
PREV=json.loads((ROOT/'history/release-manifest-v0.49.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.50.0.js').read_text()
EXP=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-experience-v1.js').read_text()
CSS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.50.0.css').read_text()
def check(value,label):
    if not value: raise SystemExit('FAIL - '+label)
    print('PASS - '+label)
check('Version: 0.50.0' in MAIN,'plugin version')
check((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.50.0','0.49.0','Workspace Experience Consolidation'),'release lineage')
check((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'schema stable')
check(not MAN['schema_migration_required'] and MAN['migration']['schema_stable'] and MAN['migration']['experience_consolidation_only_release'] and not MAN['migration']['experience_canonical_data_rewrite'],'experience-only boundary')
check(PREV['version']=='0.49.0' and PREV['release_name']=='Research Templates & Reusable Workflows','v0.49.0 predecessor retained')
check(MAN['experience_schema']=='sc-workspace-experience/1.0' and MAN['experience_preferences_schema']=='sc-workspace-experience-preferences/1.0','experience schemas')
check(MAN['workspace_experience']['density_modes']==['comfortable','compact'] and MAN['workspace_experience']['preferences_storage']=='browser-local','browser-local density preferences')
check(MAN['workspace_experience']['command_palette'] and MAN['workspace_experience']['command_shortcut']=='Ctrl/Meta+K','command palette contract')
check(MAN['workspace_experience']['primary_area_shortcuts']==['Alt+1','Alt+2','Alt+3','Alt+4','Alt+5'] and MAN['workspace_experience']['current_view_search_shortcut']=='/','keyboard navigation contract')
check("data-scw-command-open" in PHP and "data-scw-density-toggle" in PHP and "data-scw-help-open" in PHP,'experience controls rendered')
check("'/experience-contract'" in PHP and 'public function experience_contract()' in PHP,'public experience contract')
check('sc-workspace-experience-v1.js' in PHP and 'workspace-v0.50.0.js' in PHP and 'workspace-v0.50.0.css' in PHP,'v0.50 assets enqueued')
check('routeForShortcut' in EXP and 'focusCurrentSearch' in EXP and 'canonicalDataMutation:false' in EXP and 'automaticAi:false' in EXP,'experience runtime governance')
check('.scw-editorial-header-bar{height:4px' in CSS and 'editorialHeaderRulePx:4' in EXP,'4px editorial header retained')
check('min-height:44px' in CSS and 'overflow-x:auto' in CSS and 'scroll-snap-type:x proximity' in CSS,'responsive interaction hardening')
check((REG['public_version'],REG['previous_version'])==('0.50.0','0.49.0'),'registry lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0500'" in REGPHP and "PENDING_KEY = 'sc_workspace_registry_pending_v0500'" in REGPHP and 'LEGACY_PENDING_KEY_V0490' in REGPHP,'registry retry lineage')
check('rootVersion(){ const el=document.querySelector' in JS and "'0.50.0'" in JS,'main runtime current version')
files=list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.50.0.json',ROOT/'registry/workspace-product-record-v0.50.0.json']
for f in files: json.loads(f.read_text())
print(f'PASS - {len(files)} JSON schema/release records')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.50.0 — Workspace Experience Consolidation')
